mapper.select:
SELECT o.id, o.order_no, o.user_id, u.username, o.total_amount, o.freight_amount, o.pay_amount, o.status, o.receiver_name, o.receiver_phone, o.expire_time, o.pay_time, o.create_time, (SELECT COUNT(*) FROM order_item oi WHERE oi.order_id = o.id) AS item_count, (SELECT COALESCE(SUM(oi.quantity), 0) FROM order_item oi WHERE oi.order_id = o.id) AS total_quantity FROM orders o LEFT JOIN sys_user u ON u.id = o.user_id WHERE o.deleted = 0
AND o.user_id = #{query.userId}
AND o.order_no = #{query.orderNo}
AND o.status = #{query.status}
AND o.create_time >= #{query.startTime}
AND o.create_time <= #{query.endTime}
ORDER BY o.id DESC
